CREATE TABLE users (id INTEGER PRIMARY KEY AUTOINCREMENT, username TEXT NOT NULL UNIQUE, password_hash TEXT NOT NULL, role TEXT NOT NULL, first_name TEXT NOT NULL, last_name TEXT NOT NULL, email TEXT NOT NULL UNIQUE, phone TEXT NOT NULL, province TEXT, city TEXT, status TEXT NOT NULL DEFAULT 'active', created_at INTEGER NOT NULL);
CREATE TABLE lawyers (id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER NOT NULL REFERENCES users(id), license_number TEXT NOT NULL, specialties TEXT NOT NULL, bio TEXT NOT NULL, phone_price INTEGER NOT NULL, text_price INTEGER NOT NULL, in_person_price INTEGER, rating REAL NOT NULL DEFAULT 0, verified INTEGER NOT NULL DEFAULT 0, featured INTEGER NOT NULL DEFAULT 0, online INTEGER NOT NULL DEFAULT 0, in_person_enabled INTEGER NOT NULL DEFAULT 0);
CREATE TABLE questions (id INTEGER PRIMARY KEY AUTOINCREMENT, client_id INTEGER REFERENCES users(id), lawyer_id INTEGER REFERENCES lawyers(id), topic TEXT NOT NULL, body TEXT NOT NULL, kind TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'new', publish_allowed INTEGER NOT NULL DEFAULT 0, created_at INTEGER NOT NULL);
CREATE TABLE answers (id INTEGER PRIMARY KEY AUTOINCREMENT, question_id INTEGER NOT NULL REFERENCES questions(id), lawyer_id INTEGER NOT NULL REFERENCES lawyers(id), body TEXT NOT NULL, published INTEGER NOT NULL DEFAULT 0, created_at INTEGER NOT NULL);
CREATE TABLE consultations (id INTEGER PRIMARY KEY AUTOINCREMENT, client_id INTEGER NOT NULL REFERENCES users(id), lawyer_id INTEGER NOT NULL REFERENCES lawyers(id), type TEXT NOT NULL, topic TEXT NOT NULL, scheduled_at INTEGER, amount INTEGER NOT NULL, payment_status TEXT NOT NULL, status TEXT NOT NULL, created_at INTEGER NOT NULL);
CREATE TABLE orders (id INTEGER PRIMARY KEY AUTOINCREMENT, client_id INTEGER NOT NULL REFERENCES users(id), consultation_id INTEGER REFERENCES consultations(id), amount INTEGER NOT NULL, status TEXT NOT NULL, tracking_code TEXT, created_at INTEGER NOT NULL, paid_at INTEGER);
CREATE TABLE reviews (id INTEGER PRIMARY KEY AUTOINCREMENT, client_id INTEGER NOT NULL REFERENCES users(id), lawyer_id INTEGER NOT NULL REFERENCES lawyers(id), type TEXT NOT NULL, body TEXT NOT NULL, rating INTEGER NOT NULL, visible INTEGER NOT NULL DEFAULT 0, created_at INTEGER NOT NULL);
CREATE TABLE appointment_slots (id INTEGER PRIMARY KEY AUTOINCREMENT, lawyer_id INTEGER NOT NULL REFERENCES lawyers(id), starts_at INTEGER NOT NULL, ends_at INTEGER NOT NULL, status TEXT NOT NULL DEFAULT 'available');
CREATE TABLE files (id INTEGER PRIMARY KEY AUTOINCREMENT, owner_id INTEGER NOT NULL REFERENCES users(id), question_id INTEGER REFERENCES questions(id), object_key TEXT NOT NULL, file_name TEXT NOT NULL, mime_type TEXT NOT NULL, size INTEGER NOT NULL, created_at INTEGER NOT NULL);
CREATE TABLE bookmarks (id INTEGER PRIMARY KEY AUTOINCREMENT, client_id INTEGER NOT NULL REFERENCES users(id), lawyer_id INTEGER NOT NULL REFERENCES lawyers(id), created_at INTEGER NOT NULL);
CREATE TABLE messages (id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER REFERENCES users(id), kind TEXT NOT NULL, subject TEXT NOT NULL, body TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'new', created_at INTEGER NOT NULL);
CREATE TABLE articles (id INTEGER PRIMARY KEY AUTOINCREMENT, slug TEXT NOT NULL UNIQUE, title TEXT NOT NULL, excerpt TEXT NOT NULL, body TEXT NOT NULL, category TEXT NOT NULL, tags TEXT, author_id INTEGER REFERENCES users(id), status TEXT NOT NULL DEFAULT 'draft', published_at INTEGER);
CREATE TABLE admin_permissions (id INTEGER PRIMARY KEY AUTOINCREMENT, admin_id INTEGER NOT NULL REFERENCES users(id), permission TEXT NOT NULL, allowed INTEGER NOT NULL DEFAULT 0);
CREATE INDEX questions_status_idx ON questions(status);
CREATE INDEX consultations_client_idx ON consultations(client_id);
CREATE INDEX consultations_lawyer_idx ON consultations(lawyer_id);
